    and c.del_flag = '0'
    and (c.customer_name like concat('%',#{customerName},'%') or c.company_name like concat('%',#{customerName},'%') or c.mobile like concat('%',#{customerName},'%'))
    and c.customer_type = #{customerType}
    and c.industry = #{industry}
    and c.customer_level = #{customerLevel}
    and c.owner_id = #{ownerId}
    and exists (select 1 from biz_customer_tag_rel r where r.customer_id = c.customer_id and r.tag_id = #{tagId})


order by c.update_time desc, c.customer_id desc

select * from biz_customer_tag
and tag_name like concat('%',#{tagName},'%') and status = #{status}
order by order_num, tag_id

