update biz_contract c
inner join biz_customer target on target.customer_id=#{toId}
set c.customer_id=#{toId}, c.customer_name=target.customer_name, c.update_by=#{updateBy}, c.update_time=sysdate()
where c.customer_id=#{fromId}
and c.del_flag='0'
